const READINESS_TIMEOUT_MS = 30_000;
const POLL_INTERVAL_MS = 500;

// A newly created Neon preview branch is "created" before it is ready to serve
// queries. Poll a lightweight query with backoff until it succeeds, so the
// first real query does not race branch readiness and time out.
export async function waitForBranchReady(sql) {
  const deadline = Date.now() + READINESS_TIMEOUT_MS;
  let lastError;
  while (Date.now() < deadline) {
    try {
      await sql`select 1`;
      return;
    } catch (err) {
      lastError = err;
      await new Promise((r) => setTimeout(r, POLL_INTERVAL_MS));
    }
  }
  throw new Error(
    `Neon branch was not ready within ${READINESS_TIMEOUT_MS}ms: ${lastError?.message ?? lastError}`
  );
}

export async function createBranchAndQuery(neon, sql) {
  await neon.createBranch();
  await waitForBranchReady(sql);
  return sql`select * from users limit 1`;
}

