export async function createBranchAndQuery(neon, sql) {
  await neon.createBranch();

  // A freshly created Neon preview branch is not immediately ready to serve
  // queries — the compute needs to spin up. Poll until the branch reports
  // readiness, otherwise the first query races the branch boot and times out.
  const deadline = Date.now() + 60_000;
  while (true) {
    const branch = await neon.getBranch();
    const state = branch?.ready ?? branch?.status;
    const ready = state === true || state === "ready";
    if (ready) break;
    if (Date.now() > deadline) {
      throw new Error("Neon branch did not become ready in time");
    }
    await new Promise((r) => setTimeout(r, 500));
  }

  return sql`select * from users limit 1`;
}

// A freshly created Neon preview branch is not immediately ready to serve
// queries: the compute must spin up first. Running the first query before the
// branch is ready races the boot and times out. Wait for readiness first.
async function waitForBranchReady(neon, { timeoutMs = 60_000, intervalMs = 500 } = {}) {
  const deadline = Date.now() + timeoutMs;
  while (true) {
    const branch = await neon.getBranch();
    const state = branch?.ready ?? branch?.status;
    if (state === true || state === "ready") return branch;
    if (Date.now() > deadline) {
      throw new Error("Neon branch did not become ready in time");
    }
    await new Promise((r) => setTimeout(r, intervalMs));
  }
}

export async function createBranchAndQuery(neon, sql) {
  await neon.createBranch();
  await waitForBranchReady(neon);
  const runQuery = () => sql`select * from users limit 1`;
  return runQuery();
}

export async function createBranchAndQuery(neon, sql) {
  await neon.createBranch();
  // Neon preview branches aren't immediately ready: querying right after
  // creation can time out. Wait until the branch reports ready first.
  await neon.waitForReady();
  const result = await sql`select * from users limit 1`;
  return result;
}

