export const mutation = {
  onMutate: async (next) => {
    const previous = cache.get(next.id);
    cache.set(next.id, next);
    return { previous };
  },
  onError: (_error, _vars, context) => {
    if (context?.previous) {
      cache.set(context.previous.id, context.previous);
    }
    cache.invalidate();
  },
};

