// Release-aware sourcemap handling.
//
// Stack traces stay unsymbolicated when the release associated with the
// uploaded source maps does not match the release the runtime SDK reports
// in Sentry.init(). Tying the upload to a single, deterministic release
// value (here derived from the build, with an explicit override) and
// removing the public `.map` files after upload keeps the two in sync.
const RELEASE =
  process.env.SENTRY_RELEASE ||
  // Fall back to a build-derived identifier so CI and local builds agree.
  `release@${process.env.npm_package_version ?? "0.0.0"}`;

export default {
  release: {
    // Injected into both the CLI upload and the runtime SDK so the values match.
    name: RELEASE,
    inject: true,
  },
  sourcemaps: {
    assets: "./dist",
    // Upload maps from the exact build artifact for this release.
    release: RELEASE,
    filesToDeleteAfterUpload: ["./dist/**/*.map"],
  },
};

// Release-aware sourcemap handling.
//
// Stack traces stay unsymbolicated when the release bound to the uploaded
// source maps does not match the release the runtime SDK reports in
// Sentry.init(). Tying the upload to a single, deterministic release value
// (overridable via SENTRY_RELEASE) and removing the public `.map` files
// after upload keeps both sides in sync so Sentry can symbolicate events.
const RELEASE =
  process.env.SENTRY_RELEASE ||
  // Fall back to a build-derived identifier so CI and local builds agree.
  `release@${process.env.npm_package_version ?? "0.0.0"}`;

export default {
  release: {
    // Shared by the CLI upload and the runtime SDK so the values match.
    name: RELEASE,
    inject: true,
  },
  sourcemaps: {
    assets: "./dist",
    // Upload maps from the exact build artifact for this release.
    release: RELEASE,
    filesToDeleteAfterUpload: ["./dist/**/*.map"],
  },
};

export default {
  // A release tag is required for Sentry to match uploaded artifacts
  // (sourcemaps) to a specific deployed version; without it, stack traces
  // stay unsymbolicated even when maps are uploaded.
  release: {
    name: process.env.SENTRY_RELEASE,
    setCommits: { auto: true },
  },
  sourcemaps: {
    assets: "./dist",
    // Delete the source maps after upload so they are not served publicly,
    // which would expose original source code.
    filesAfterUpload: ["./dist/**/*.js.map"],
    // Without a matching url prefix, Sentry cannot resolve the maps.
    url: "~/",
  },
};

