    inject: false,
  },
  sourcemaps: {
    assets: "./dist",
    // Keep symbolicated stacks working in production by telling Sentry
    // which files belong to the release, then dropping them after upload.
    filesAfterUpload: ["**/*.js.map"],
    deleteFilesAfterUpload: true,
  },
};

